using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model before building the app so the .zip exists for the pool
var trainer = new ModelTrainingService(
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger<ModelTrainingService>());
var metrics = trainer.TrainAndEvaluate();

builder.Services.AddSingleton(metrics);
builder.Services.AddSingleton(trainer);
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

var app = builder.Build();

app.Logger.LogInformation(
    "Training complete — MicroAccuracy: {Micro:P2}, MacroAccuracy: {Macro:P2}",
    metrics.MicroAccuracy, metrics.MacroAccuracy);

app.MapControllers();
app.Run();

